import sys,collections
sys.path.insert(0,'/private/tmp/claude-501/-Users-kevingalligan-devel-framejob/9cfd7405-83ec-4caa-905f-7b97a20f2cc9/scratchpad/inventory/work-export')
from load import *
R=allrecs()
byid={x['id']:x for x in R}
claimed={};rej={}
for f in sorted(glob.glob(B+'features/*.json')):
    d=json.load(open(f)); s=d.get('section')
    for ft in d['features']:
        for i in ft.get('raw_ids',[]): claimed[i]=(s,ft['id'],ft['page'])
    for r in d.get('rejected',[]):
        rej.setdefault(r['raw_id'],[]).append((s,r['reason']))
print('sections done',sorted(os.path.basename(f) for f in glob.glob(B+'features/*.json')))
# claimed by others, of area export
print('--area export claimed by others')
for x in R:
    if x.get('area')=='export' and x['id'] in claimed: print(x['id'],x['name'],claimed[x['id']])
print('--rejected belongs to export (all)')
n=0
L=[]
for i,v in rej.items():
    if any('export' in r[1] for r in v):
        L.append(i)
print(len(L))
for i in L:
    x=byid.get(i)
    print(i,'|',x and x.get('area'),'|',x and x['name'],'|',rej[i],'| claimed:',claimed.get(i))
print('--guide-export claimed by others')
for x in R:
    if x['_f']=='guide-export.json' and x['id'] in claimed: print(x['id'],x['name'],x.get('area'),claimed[x['id']])
t=json.load(open(B+'taxonomy.json'))
for s in t['sections']:
    for p in s['pages']:
        sc=p.get('scope','')
        if s['id']!='export' and re.search(r'\bexport|render_frame|save frame|chapter|stem|deliverable',sc+p['slug'],re.I):
            print(s['id'],p['slug'],'::',sc)

